class I{String s(boolean P,String[]S){int a[]=S[0].chars().map(c->c-48).toArray(),N=a.length,p[]=new int[N],n=0,r=N-1&-2;long A=0;for(int i=0;i<N;i++){p[i]=n;n+=a[i];A+=1L*(~i&1)*i*a[i]*(2*p[i]+a[i]-1)/4;}if(P){int z=a[r],i=1;x:for(;i<r;i+=2)for(int q=p[i];q<p[i]+a[i];q++){while(z<1&r>i)z=a[r-=2];int s=p[r]+z-1;if(q>=s)break x;A+=1L*r/2*(q-s);z--;}}else for(int i=r;i>0;i-=2)for(int j=1;j<i;j+=2)if(a[j]>=a[i]){A+=1L*i/2*a[i]*(p[j]-p[i]);p[i]=p[j];p[j]+=a[i];a[j]-=a[i];break;}return""+A;}}
